insert into public.suggestions (title,category,city,area,description,cost_hint,tags,lat,lng,for_who) values
($q$TORCH TORCH, Shibuya PARCO$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Officially licensed FromSoftware apparel brand on PARCO's 5th floor: Elden Ring, Dark Souls, Bloodborne, Sekiro and Armored Core tees, hoodies, jewellery and bags, designed like streetwear rather than fan merch. The brand also has shops in Shinsaibashi PARCO (Osaka) and Nagoya PARCO. Usually 11:00–21:00.$q$,$q$Free to browse$q$,array[$q$fromsoftware$q$,$q$elden-ring$q$,$q$dark-souls$q$,$q$apparel$q$,$q$games$q$,$q$shop$q$]::text[],35.6621,139.6985,$q$josh$q$),
($q$Capcom Store Tokyo$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Capcom's flagship shop on Shibuya PARCO's 6th floor, one floor above TORCH TORCH. Monster Hunter, Resident Evil and Street Fighter clothing, homeware and art books alongside the figures. Pair the two in one visit.$q$,$q$Free to browse$q$,array[$q$capcom$q$,$q$monster-hunter$q$,$q$resident-evil$q$,$q$apparel$q$,$q$games$q$,$q$shop$q$]::text[],35.6621,139.6985,$q$josh$q$),
($q$Nintendo TOKYO$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Shibuya$q$,$q$Nintendo's own shop, also on PARCO's 6th floor next to the Pokémon Center and Jump Shop. Good for Zelda and Animal Crossing clothing, kitchenware and stationery that you won't find in normal toy shops. Busy: a timed entry ticket is sometimes needed at peak times.$q$,$q$Free to browse$q$,array[$q$nintendo$q$,$q$zelda$q$,$q$mario$q$,$q$apparel$q$,$q$games$q$,$q$shop$q$]::text[],35.6621,139.6985,$q$both$q$),
($q$Square Enix ARTNIA$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Higashi-Shinjuku$q$,$q$Square Enix's café and shop at its Shinjuku Eastside Square HQ. Final Fantasy, Dragon Quest and NieR goods, art prints and accessories, plus themed drinks with collectible coasters. A newer licensed Square Enix Café & Shop also opened in June 2026 near Shinjuku-sanchome, so check which has the better range.$q$,$q$Free to browse, café extra$q$,array[$q$square-enix$q$,$q$final-fantasy$q$,$q$dragon-quest$q$,$q$cafe$q$,$q$games$q$,$q$shop$q$]::text[],35.6975,139.708,$q$josh$q$),
($q$EVANGELION STORE TOKYO-01$q$,$q$shopping$q$,$q$Tokyo$q$,$q$Ikebukuro$q$,$q$Official Eva shop on Ikebukuro PARCO's 2nd floor, with character voices on the tannoy. Best for the RADIO EVA fashion label (jackets, caps and collabs with brands like KANGOL) rather than figures. 11:00–21:00.$q$,$q$Caps ~¥15,000$q$,array[$q$evangelion$q$,$q$anime$q$,$q$apparel$q$,$q$shop$q$]::text[],35.73,139.711,$q$josh$q$),
($q$Hakone-Yumoto EVA-YA$q$,$q$shopping$q$,$q$Hakone / Fuji$q$,$q$Hakone-Yumoto$q$,$q$Little Evangelion shop in Hakone (Tokyo-3 in the series), handy for a souvenir you can't get in Tokyo. A quick stop on the way into Hakone on a drive day. Check it's open before making a detour.$q$,$q$Free to browse$q$,array[$q$evangelion$q$,$q$anime$q$,$q$shop$q$]::text[],35.2325,139.105,$q$josh$q$),
($q$Nintendo KYOTO$q$,$q$shopping$q$,$q$Kyoto$q$,$q$Shijo-Kawaramachi$q$,$q$Nintendo's shop on the 7th floor of Kyoto Takashimaya S.C., in the company's home town. Similar range to Tokyo but usually calmer, with a life-size Mario photo spot. Pairs with the Nintendo Museum in Uji.$q$,$q$Free to browse$q$,array[$q$nintendo$q$,$q$zelda$q$,$q$mario$q$,$q$games$q$,$q$shop$q$]::text[],35.0035,135.7686,$q$both$q$),
($q$TORCH TORCH, Shinsaibashi PARCO$q$,$q$shopping$q$,$q$Osaka$q$,$q$Shinsaibashi$q$,$q$The Osaka branch of the FromSoftware apparel shop, so you can leave the Elden Ring hoodie until the end of the trip. Capcom Store Osaka is in the same PARCO.$q$,$q$Free to browse$q$,array[$q$fromsoftware$q$,$q$elden-ring$q$,$q$dark-souls$q$,$q$apparel$q$,$q$games$q$,$q$shop$q$]::text[],34.6745,135.5013,$q$josh$q$),
($q$Capcom Store Osaka$q$,$q$shopping$q$,$q$Osaka$q$,$q$Shinsaibashi$q$,$q$Capcom's Osaka shop in Shinsaibashi PARCO (it opened on the 6th floor; check the floor guide). Same mix of Monster Hunter and Resident Evil clothing and homeware as Tokyo. Mandarake Grand Chaos is a few minutes' walk away.$q$,$q$Free to browse$q$,array[$q$capcom$q$,$q$monster-hunter$q$,$q$resident-evil$q$,$q$apparel$q$,$q$games$q$,$q$shop$q$]::text[],34.6745,135.5013,$q$josh$q$),
($q$Nintendo OSAKA$q$,$q$shopping$q$,$q$Osaka$q$,$q$Umeda$q$,$q$Nintendo's shop on the 13th floor of Daimaru Umeda, above Osaka Station. Easy last-day stop for anything you didn't fit in your bag in Tokyo, since it's right by the airport trains.$q$,$q$Free to browse$q$,array[$q$nintendo$q$,$q$zelda$q$,$q$mario$q$,$q$games$q$,$q$shop$q$]::text[],34.703,135.497,$q$both$q$);
